syntax:
template <class... U1, class... U2>
std::tuple<U1...>& operator=(std::tuple<U2...>&& other);

//Alternatively, a more specialized version:
template <class U1, class U2>
std::tuple<U1, U2>& operator=(std::pair<U1, U2>&& other);

code_example:
template <class U1, class U2>
std::tuple<U1, U2>& operator=(std::pair<U1, U2>&& other) {
  std::get<0>(*this) = std::move(other.first);
  std::get<1>(*this) = std::move(other.second);
  return *this;
}

int main() {
  std::tuple<int, std::string> t1 = {1, "hello"};
  auto t2 = std::make_pair(2, std::string("world"));
  t1 = std::move(t2); //Uses the custom assignment operator
  std::cout << std::get<0>(t1) << ", " << std::get<1>(t1) << std::endl; // Output: 2, world
  return 0;
}
